(function(root){
'use strict';
const roster=[['Tomi','imagery','publish'],['Bayo','satire','compete'],['Sade','rhythm','collaborate'],['Nnamdi','structure','practice'],['Zara','imagery','publish'],['Femi','performance','compete'],['Ada','structure','mentor'],['Kola','rhythm','practice'],['Muna','imagery','collaborate'],['Dami','satire','publish'],['Ife','performance','compete'],['Reni','rhythm','mentor']];
const lines=['The rain rehearses on a roof / before the morning finds its voice.','A bus keeps all our borrowed names / and leaves the silence at the stop.','I fold the day into a pocket / where an unfinished song can sleep.','The market counts its little suns / in oranges and open palms.'];
function create(seed=2010){return {version:1,seed,day:1,name:'New voice',city:'Ogbomoso',energy:80,money:3000,craft:12,delivery:10,reputation:0,prepared:0,research:0,poem:'',wall:[],log:['You arrive in a fictional Ogbomoso poetry community, January 2010.'],npcs:roster.map(([name,style,goal],i)=>({id:i,name,style,goal,relationship:0,skill:14+i,funds:500+i*100,works:0,activity:'Working on a first draft',memory:[]})),entered:[],posts:0};}
function rand(s){s.seed=(Math.imul(s.seed,1664525)+1013904223)>>>0;return s.seed/4294967296;}
function note(s,msg){s.log.unshift(msg);s.log=s.log.slice(0,80);}
function tick(s){s.day++;s.energy=Math.min(100,s.energy+12);s.npcs.forEach(n=>{const r=rand(s);if(n.goal==='publish'&&r<.5){n.works++;n.activity='Posted a new miniature';s.wall.unshift({author:n.name,text:lines[(n.id+s.day)%lines.length],day:s.day,fiction:true});}else if(n.goal==='compete'&&n.funds>=150&&r<.7){n.funds-=150;n.skill++;n.activity='Rehearsed for the next slam';}else if(n.goal==='collaborate'&&r<.6){n.activity='Invited a peer to a joint reading';n.skill++;}else if(n.goal==='mentor'&&r<.6){n.activity='Hosted a critique circle';n.funds+=50;}else {n.activity='Revised a draft between other obligations';n.skill+=.25;n.funds+=100;}});s.wall=s.wall.slice(0,40);if(root.PoeticsOpportunities)root.PoeticsOpportunities.onDay(s);note(s,'Day '+s.day+': the community advances; poets pursue their own plans.');}
function act(s,type,arg){const costs={coach:[18,350],research:[10,200],rehearse:[16,0],post:[12,0],feedback:[10,0],openmic:[20,150],slam:[25,400],travel:[20,600]};if(type==='rest'){tick(s);s.energy=Math.min(100,s.energy+25);return {ok:true,message:'A new day begins.'};}if(type==='work'){tick(s);s.energy=Math.max(0,s.energy-15);s.money+=450;note(s,'You take a paid shift: +₦450.');return {ok:true,message:'Paid shift complete.'};}if(type==='write'){if(typeof arg!=='string'||arg.length>4000)return {ok:false,message:'Keep your draft within 4,000 characters.'};s.poem=arg;return {ok:true,message:'Draft saved on this device.'};}if(type==='name'){s.name=String(arg).trim().slice(0,40)||'New voice';return {ok:true,message:'Your pen name is saved.'};}if(!costs[type])return {ok:false,message:'Unknown action.'};const [energy,money]=costs[type];if(s.energy<energy||s.money<money)return {ok:false,message:'You need '+energy+' energy and ₦'+money+' for this action. Rest or take a paid shift.'};if(['post','openmic','slam'].includes(type)&&s.poem.trim().length<40)return {ok:false,message:'Write at least 40 characters before sharing or performing.'};if(type==='slam'&&s.entered.includes(s.day))return {ok:false,message:'You have already entered today’s slam. Advance to another day.'};if(type==='travel'&&!['Ogbomoso','Ibadan','Lagos'].includes(arg))return {ok:false,message:'Choose a destination on the fictional circuit.'};if(type==='travel'&&arg===s.city)return {ok:false,message:'You are already in '+s.city+'.'};if(type==='feedback'&&!s.npcs[arg])return {ok:false,message:'Choose a poet.'};s.energy-=energy;s.money-=money;
let msg='';if(type==='coach'){s.craft+=4;msg='Coach: choose one concrete image, then cut the explanation after it. Craft +4.';}if(type==='research'){s.research=Math.min(3,s.research+1);msg='Researcher: Bayo favours satire; Sade rehearses rhythm. A contrasting delivery can help. This is fictional opponent research.';}if(type==='rehearse'){s.delivery+=3;s.prepared=Math.min(5,s.prepared+1);msg='You rehearse pauses and breath. Delivery +3; preparation +1.';}if(type==='post'){s.wall.unshift({author:s.name,text:s.poem,day:s.day,fiction:true});s.wall=s.wall.slice(0,40);s.posts++;s.reputation+=2;msg='Your original draft reaches the wall. Reputation +2.';}if(type==='feedback'){const n=s.npcs[arg];n.relationship+=2;n.memory.push('Received your feedback on day '+s.day);s.craft++;msg='You exchange a concrete revision note with '+n.name+'. Relationship +2; craft +1.';}if(type==='travel'){s.city=arg;msg='You travel to '+arg+'. A new room, the same unfinished poem.';}if(type==='openmic'){s.reputation+=4;s.delivery+=2;msg='You perform at the fictional Lion’s Lines open mic. Reputation +4; delivery +2.';}if(type==='slam'){const words=s.poem.trim().split(/\s+/).length;const fit=arg==='intimate'?s.craft:arg==='rhythmic'?s.delivery:(s.craft+s.delivery)/2;const score=Math.round(35+Math.min(15,words/8)+(s.craft+s.delivery)*.45+fit*.3+s.prepared*3+s.research*2+rand(s)*10);const rivals=s.npcs.filter(n=>n.goal==='compete').map(n=>({name:n.name,score:Math.round(45+n.skill*.7+rand(s)*15)}));const rank=1+rivals.filter(n=>n.score>=score).length;s.entered.push(s.day);s.reputation+=rank===1?10:3;if(rank===1)s.money+=700;msg='Fictional slam: '+score+' points; place '+rank+' of '+(rivals.length+1)+'. '+rivals.map(n=>n.name+': '+n.score).join(' · ')+'. '+(rank===1?'Prize +₦700.':'Reputation +3 for showing up.')+' Game points reflect preparation, delivery choice and chance; they are not a literary verdict.';s.prepared=0;s.research=0;}note(s,msg);return {ok:true,message:msg};}
function valid(s){return s&&(!s.opportunities||(Array.isArray(s.opportunities.read)&&s.opportunities.read.every(x=>typeof x==='string')&&s.opportunities.submissions&&typeof s.opportunities.submissions==='object'&&!Array.isArray(s.opportunities.submissions)&&Object.values(s.opportunities.submissions).every(e=>e&&typeof e.poem==='string'&&e.poem.length<=4000&&typeof e.author==='string'&&Number.isInteger(e.day)&&Number.isInteger(e.deadline)&&Number.isFinite(e.craft)&&['competition','anthology'].includes(e.type))&&s.opportunities.resolved&&typeof s.opportunities.resolved==='object'&&!Array.isArray(s.opportunities.resolved)&&Object.values(s.opportunities.resolved).every(e=>e&&typeof e.message==='string'&&typeof e.success==='boolean'&&Number.isInteger(e.day))))&&s.version===1&&Number.isInteger(s.day)&&s.day>0&&Number.isInteger(s.seed)&&typeof s.poem==='string'&&s.poem.length<=4000&&typeof s.name==='string'&&s.name.length<=40&&['Ogbomoso','Ibadan','Lagos'].includes(s.city)&&['energy','money','craft','delivery','reputation','prepared','research'].every(k=>Number.isFinite(s[k])&&s[k]>=0)&&s.energy<=100&&Array.isArray(s.npcs)&&s.npcs.length===12&&s.npcs.every((n,i)=>n.id===i&&n.name===roster[i][0]&&n.style===roster[i][1]&&n.goal===roster[i][2]&&['relationship','skill','funds','works'].every(k=>Number.isFinite(n[k])&&n[k]>=0)&&typeof n.activity==='string'&&Array.isArray(n.memory)&&n.memory.every(x=>typeof x==='string'))&&Array.isArray(s.wall)&&s.wall.length<=40&&s.wall.every(p=>typeof p.author==='string'&&p.author.length<=40&&typeof p.text==='string'&&p.text.length<=4000&&Number.isInteger(p.day)&&p.fiction===true)&&Number.isInteger(s.posts)&&s.posts>=0&&Array.isArray(s.log)&&s.log.length<=80&&s.log.every(x=>typeof x==='string')&&Array.isArray(s.entered)&&s.entered.every(d=>Number.isInteger(d)&&d>0);}
const api={create,act,tick,valid};if(typeof module!=='undefined')module.exports=api;root.PoeticsEngine=api;
})(typeof window!=='undefined'?window:globalThis);
